import{_ as t,o as d,c as o,a2 as a}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"搜尋語法","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/user-guide/search-syntax.md","filePath":"zh-TW/user-guide/search-syntax.md","lastUpdated":1787649438000}'),c={name:"zh-TW/user-guide/search-syntax.md"};function l(s,e,i,n,r,p){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="搜尋語法" tabindex="-1">搜尋語法 <a class="header-anchor" href="#搜尋語法" aria-label="Permalink to &quot;搜尋語法&quot;">​</a></h1><p>Lertaro 的搜尋框遠不只是單純的文字比對。它配備了極速的搜尋引擎，支援模糊跳躍比對、邏輯運算子、詞邊界修飾符、磁碟機與路徑鎖定、二次篩選標記（Query Tokens）以及多語言智能別名，所有語法均可在同一條查詢中自由混合使用。</p><h2 id="_1-基礎比對模式與大小寫" tabindex="-1">1. 基礎比對模式與大小寫 <a class="header-anchor" href="#_1-基礎比對模式與大小寫" aria-label="Permalink to &quot;1. 基礎比對模式與大小寫&quot;">​</a></h2><h3 id="模糊比對-預設" tabindex="-1">模糊比對（預設） <a class="header-anchor" href="#模糊比對-預設" aria-label="Permalink to &quot;模糊比對（預設）&quot;">​</a></h3><p>Lertaro 預設啟用模糊比對（Fuzzy Matching）。只需輸入關鍵字的任意部分，只要字元按先後順序出現在檔案或資料夾名稱中，即使不連續也能精準命中：</p><table tabindex="0"><thead><tr><th style="text-align:left;">輸入範例</th><th style="text-align:left;">比對結果範例</th><th style="text-align:left;">說明</th></tr></thead><tbody><tr><td style="text-align:left;"><code>ltro</code></td><td style="text-align:left;"><code>Lertaro.exe</code></td><td style="text-align:left;">字元按 <code>l</code> → <code>t</code> → <code>r</code> → <code>o</code> 順序跳躍命中（<strong>L</strong>er<strong>t</strong>a<strong>ro</strong>.exe）</td></tr><tr><td style="text-align:left;"><code>vsc</code></td><td style="text-align:left;"><code>Visual Studio Code.lnk</code></td><td style="text-align:left;">命中各單詞首字母（<strong>V</strong>isual <strong>S</strong>tudio <strong>C</strong>ode）</td></tr><tr><td style="text-align:left;"><code>rt-fin</code></td><td style="text-align:left;"><code>Q3-report-final.docx</code></td><td style="text-align:left;">命中連續子字串（Q3-repo<strong>rt-fin</strong>al.docx）</td></tr></tbody></table><p>在<strong>設定 → 一般 → 系統 → 啟用模糊比對</strong>中關閉該開關後，一般搜尋詞（未附加任何運算子）將轉為精確子字串比對——輸入 <code>abc</code> 將只比對包含連續 <code>abc</code> 的名稱，不再比對 <code>a-b-c</code>。該開關僅改變未帶修飾符的一般詞，後文介紹的所有運算子行為均保持一致。</p><h3 id="大小寫智能識別-smart-case" tabindex="-1">大小寫智能識別（Smart Case） <a class="header-anchor" href="#大小寫智能識別-smart-case" aria-label="Permalink to &quot;大小寫智能識別（Smart Case）&quot;">​</a></h3><ul><li><strong>全小寫查詢</strong>：預設不區分大小寫。例如輸入 <code>myfile</code> 可命中 <code>myfile</code>、<code>MyFile</code>、<code>MYFILE</code> 等。</li><li><strong>包含大寫字母</strong>：一旦詞中包含任意大寫字母，該詞將自動轉為<strong>大小寫敏感</strong>。例如輸入 <code>MyFile</code> 只會比對 <code>MyFile</code>，而不會比對全小寫的 <code>myfile</code>。</li></ul><h2 id="_2-多詞組合與邏輯運算" tabindex="-1">2. 多詞組合與邏輯運算 <a class="header-anchor" href="#_2-多詞組合與邏輯運算" aria-label="Permalink to &quot;2. 多詞組合與邏輯運算&quot;">​</a></h2><h3 id="空格-and-與" tabindex="-1">空格：AND（與） <a class="header-anchor" href="#空格-and-與" aria-label="Permalink to &quot;空格：AND（與）&quot;">​</a></h3><p>多個關鍵字之間使用空格分隔，表示同時滿足所有條件。各個關鍵字在檔案名稱中出現的先後順序<strong>不受限制</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>report final 2024</span></span></code></pre></div><p>上述輸入可以同時命中 <code>2024-Q3-report-final.docx</code> 與 <code>final_report_2024.pdf</code>。</p><h3 id="豎線-or-或" tabindex="-1">豎線 <code>|</code>：OR（或） <a class="header-anchor" href="#豎線-or-或" aria-label="Permalink to &quot;豎線 `|`：OR（或）&quot;">​</a></h3><p>使用豎線 <code>|</code> 分隔關鍵字，表示滿足其中任意一個條件即可：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>png | jpg | gif</span></span></code></pre></div><p>可自由混合 AND 與 OR 邏輯。例如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>report | summary 2024</span></span></code></pre></div><p>表示尋找包含 <code>report</code> 或 <code>summary</code>，且同時包含 <code>2024</code> 的檔案。在 OR 查詢中，結果名稱中所有命中條件的關鍵字都會同步反白顯示。</p><h3 id="運算優先級-or-優先於-and" tabindex="-1">運算優先級：OR 優先於 AND <a class="header-anchor" href="#運算優先級-or-優先於-and" aria-label="Permalink to &quot;運算優先級：OR 優先於 AND&quot;">​</a></h3><p>在同一查詢中混合使用空格（AND）與豎線 <code>|</code>（OR）時，<code>|</code> 的優先級<strong>高於</strong>空格：<code>|</code> 兩側的詞會先合併為同一個 OR 組，空格分隔的各組之間再取 AND。查詢不支援括號，不支援用括號改變這種結合順序。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>report | summary 2024 | draft</span></span></code></pre></div><p>等價於 <code>(report OR summary) AND (2024 OR draft)</code>。</p><p>注意：<code>|</code> 必須作為獨立詞並以空格與兩側分隔，<code>a|b</code> 或 <code>a |b</code> 不會按 OR 解析；也不要把 <code>!</code> 排除詞放進 <code>|</code> 的 OR 組（如 <code>b | !c</code>），它會被解析為「b 比對或 c 不比對」，若想排除某個詞，請讓它作為獨立的空格條件（如 <code>b !c</code>）。</p><h3 id="詞內空格與短語引用" tabindex="-1">詞內空格與短語引用 <a class="header-anchor" href="#詞內空格與短語引用" aria-label="Permalink to &quot;詞內空格與短語引用&quot;">​</a></h3><p>若要搜尋本身包含空格的短語，可以使用反斜線轉義空格 <code>\\ </code>，或使用單引號 <code>&#39;...&#39;</code> / 雙引號 <code>&quot;...&quot;</code> 包裹短語：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>final\\ report</span></span>\n<span class="line"><span>&#39;final report&#39;</span></span></code></pre></div><p>上述寫法均會將 <code>final report</code> 視為一個包含空格的完整詞，而不是拆分為兩個獨立的 AND 關鍵字。</p><h3 id="貼上多行文字自動摺疊為-or" tabindex="-1">貼上多行文字自動摺疊為 OR <a class="header-anchor" href="#貼上多行文字自動摺疊為-or" aria-label="Permalink to &quot;貼上多行文字自動摺疊為 OR&quot;">​</a></h3><p>當從試算表、文字檔案或記錄檔中複製多行文字（一行一個檔案名稱）並直接貼上到搜尋框中時，Lertaro 會自動將各行用 <code>|</code> 拼接摺疊為一條 OR 查詢（自動過濾空白行）：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>123</span></span>\n<span class="line"><span>456</span></span>\n<span class="line"><span>678</span></span></code></pre></div><p>貼上後將自動轉換為：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>123 | 456 | 678</span></span></code></pre></div><h2 id="_3-運算子修飾符大全" tabindex="-1">3. 運算子修飾符大全 <a class="header-anchor" href="#_3-運算子修飾符大全" aria-label="Permalink to &quot;3. 運算子修飾符大全&quot;">​</a></h2><h3 id="運算子速查表" tabindex="-1">運算子速查表 <a class="header-anchor" href="#運算子速查表" aria-label="Permalink to &quot;運算子速查表&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">運算子 / 語法</th><th style="text-align:left;">類型</th><th style="text-align:left;">效果說明</th><th style="text-align:left;">輸入範例</th><th style="text-align:left;">比對結果範例</th></tr></thead><tbody><tr><td style="text-align:left;"><em>(無)</em></td><td style="text-align:left;">預設模糊</td><td style="text-align:left;">字元按順序出現在名稱任意位置（開啟模糊時）</td><td style="text-align:left;"><code>report</code></td><td style="text-align:left;"><code>Q3-report-final.docx</code></td></tr><tr><td style="text-align:left;"><code>!</code></td><td style="text-align:left;">排除</td><td style="text-align:left;">排除名稱中包含該精確子字串的所有結果</td><td style="text-align:left;"><code>!temp</code></td><td style="text-align:left;">過濾掉含有 <code>temp</code> 的檔案</td></tr><tr><td style="text-align:left;"><code>&#39;</code></td><td style="text-align:left;">翻轉精確性</td><td style="text-align:left;">模糊開啟時轉精確子字串；模糊關閉時轉模糊比對</td><td style="text-align:left;"><code>&#39;report</code></td><td style="text-align:left;">必須包含連續的 <code>report</code> 子字串</td></tr><tr><td style="text-align:left;"><code>&#39;...&#39;</code></td><td style="text-align:left;">詞邊界比對</td><td style="text-align:left;">精確子字串比對，且要求位於單詞邊界（非單詞內部）</td><td style="text-align:left;"><code>&#39;app&#39;</code></td><td style="text-align:left;">比對 <code>app.exe</code>、<code>my-app.log</code>，不比對 <code>whatsapp.exe</code></td></tr><tr><td style="text-align:left;"><code>^</code></td><td style="text-align:left;">前綴比對</td><td style="text-align:left;">檔案/資料夾名稱必須以此內容開頭</td><td style="text-align:left;"><code>^IMG</code></td><td style="text-align:left;"><code>IMG_20240101.jpg</code>（不比對 <code>MY_IMG.jpg</code>）</td></tr><tr><td style="text-align:left;"><code>$</code></td><td style="text-align:left;">後綴比對</td><td style="text-align:left;">檔案/資料夾名稱必須以此內容結尾</td><td style="text-align:left;"><code>.pdf$</code></td><td style="text-align:left;"><code>document.pdf</code>（不比對 <code>document.pdf.bak</code>）</td></tr><tr><td style="text-align:left;"><code>^...$</code></td><td style="text-align:left;">完全比對</td><td style="text-align:left;">檔案/資料夾名稱必須與此內容完全相等</td><td style="text-align:left;"><code>^readme.md$</code></td><td style="text-align:left;">僅精確比對 <code>readme.md</code></td></tr><tr><td style="text-align:left;"><code>|</code></td><td style="text-align:left;">或邏輯</td><td style="text-align:left;">比對管線符號任意一側的條件</td><td style="text-align:left;"><code>doc | pdf</code></td><td style="text-align:left;">比對名稱包含 <code>doc</code> 或 <code>pdf</code> 的項目</td></tr></tbody></table><h3 id="運算子進階說明與實戰組合" tabindex="-1">運算子進階說明與實戰組合 <a class="header-anchor" href="#運算子進階說明與實戰組合" aria-label="Permalink to &quot;運算子進階說明與實戰組合&quot;">​</a></h3><ol><li><strong>排除修飾符 <code>!</code></strong>：<code>!term</code> 會將包含 <code>term</code> 精確子字串的結果直接剔除。排除項不會進行拼音擴展，以避免誤排除無辜檔案。</li><li><strong>精確性翻轉 <code>&#39;</code></strong>：在全域模糊比對開啟的狀態下，前綴 <code>&#39;</code> 可使特定關鍵字臨時走精確子字串比對。 <ul><li>例如 <code>lertaro &#39;v1.2</code> 表示 <code>lertaro</code> 走模糊搜尋，而 <code>v1.2</code> 必須作為連續字元精準出現。</li><li>即便開啟了精確搜尋，程式仍將比對存在拼音別名的檔名，如 <code>&#39;exe$</code> 可搜尋到 <code>古恩希爾</code>（拼音映射為 <code>gexe</code>）。</li></ul></li><li><strong>詞邊界精確比對 <code>&#39;...&#39;</code></strong>：用單引號包裹單個詞（如 <code>&#39;app&#39;</code>）時，比對引擎會檢查前後邊界（空白字元、標點符號、減號、底線或字串首尾），避免在長單詞中間發生誤命中。</li><li><strong>完全比對 <code>^...$</code></strong>：僅當 <code>^</code> 和 <code>$</code> 作用於<strong>同一個詞</strong>時生效。如果分別寫在不同詞上（如 <code>^src md$</code>），則仍分別作為前綴和後綴條件。</li></ol><p><strong>多運算子組合實戰範例</strong>：</p><ul><li><code>^IMG !.png$ 2024</code>：尋找以 <code>IMG</code> 開頭、包含 <code>2024</code>、且後綴<strong>不是</strong> <code>.png</code> 的檔案。</li><li><code>&#39;data | &#39;backup ^2024 .zip$</code>：尋找以 <code>2024</code> 開頭、以 <code>.zip</code> 結尾，且名稱中精確包含 <code>data</code> 或 <code>backup</code> 的壓縮檔。</li><li><code>^report &#39;公告 | &#39;gw .pdf$ !draft</code>：名稱以 <code>report</code> 開頭、以 <code>.pdf</code> 結尾、不包含 <code>draft</code>，且名稱中精確包含 <code>公告</code> 或 <code>gw</code> 或 <code>公文</code> 及其他符合 <code>gw</code> 拼音的文字組合（<code>&#39;公告 | &#39;gw</code> 組成一個 OR 組，其餘空格條件與它取 AND）。</li></ul><h2 id="_4-路徑模式與磁碟機限定" tabindex="-1">4. 路徑模式與磁碟機限定 <a class="header-anchor" href="#_4-路徑模式與磁碟機限定" aria-label="Permalink to &quot;4. 路徑模式與磁碟機限定&quot;">​</a></h2><h3 id="指定磁碟機" tabindex="-1">指定磁碟機 <a class="header-anchor" href="#指定磁碟機" aria-label="Permalink to &quot;指定磁碟機&quot;">​</a></h3><p>在搜尋框開頭輸入磁碟機代號加冒號，可將搜尋範圍嚴格限定在指定磁碟機：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>d: report</span></span></code></pre></div><p>空格可以省略，<code>d:report</code> 與 <code>d: report</code> 等效。</p><h3 id="完整路徑模式" tabindex="-1">完整路徑模式 <a class="header-anchor" href="#完整路徑模式" aria-label="Permalink to &quot;完整路徑模式&quot;">​</a></h3><p>當搜尋內容包含路徑分隔符號（<code>\\</code> 或 <code>/</code>）時，Lertaro 會自動切換為全路徑比對模式：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>D:\\Projects\\Lertaro</span></span></code></pre></div><p>若以路徑分隔符號結尾（如 <code>D:\\Projects\\</code>），則會直接搜尋該資料夾<strong>內部</strong>的所有子項目。</p><h3 id="智能上級資料夾回退比對-folder-matching" tabindex="-1">智能上級資料夾回退比對（Folder Matching） <a class="header-anchor" href="#智能上級資料夾回退比對-folder-matching" aria-label="Permalink to &quot;智能上級資料夾回退比對（Folder Matching）&quot;">​</a></h3><p>當針對檔案名稱的一般搜尋未填滿結果列表上限時，Lertaro 會自動使用查詢詞中未命中檔案名稱的部分去比對上級祖先資料夾名稱，無需額外語法：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>d01j dcj</span></span></code></pre></div><p>即使 <code>dcj</code> 沒有出現在檔案本身的名字中，也能找到位於名為（或拼音別名為）<code>dcj</code> 的資料夾下的 <code>d01j.txt</code> 檔案。</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>該特性要求至少有一個詞命中檔案名稱本身，且僅在檔案名稱直接比對未填滿結果時觸發。回退補全的結果始終排列在常規結果之後，絕不會頂替或打亂檔案名稱直接比對的結果。</p></div><h2 id="_5-查詢標記與二次篩選-query-tokens" tabindex="-1">5. 查詢標記與二次篩選（Query Tokens） <a class="header-anchor" href="#_5-查詢標記與二次篩選-query-tokens" aria-label="Permalink to &quot;5. 查詢標記與二次篩選（Query Tokens）&quot;">​</a></h2><p>Lertaro 支援在主搜尋詞後追加以冒號 <code>:</code>（可在<strong>設定 → 一般 → 系統 → 查詢標記總前導字元</strong>中自訂）引導的<strong>查詢標記（Query Tokens）</strong>，對初篩結果進行鏈式二次篩選與排序。</p><p>支援在單個 <code>:</code> 後使用逗號 <code>,</code> 組合多個標記，例如 <code>report :@doc,M-,:-F</code>。</p><h3 id="檔案分類篩選-分類名" tabindex="-1">檔案分類篩選（<code>:@&lt;分類名&gt;</code>） <a class="header-anchor" href="#檔案分類篩選-分類名" aria-label="Permalink to &quot;檔案分類篩選（`:@&lt;分類名&gt;`）&quot;">​</a></h3><p>快速套用預設的副檔名分類規則，支援使用 <code>|</code> 組合多個分類：</p><ul><li><code>:@doc</code>：文件類（<code>*.doc; *.docx; *.pdf; *.txt; *.ppt; *.pptx; *.xls; *.xlsx; *.csv; *.rtf; *.md; *.wps</code>）</li><li><code>:@img</code>：圖片類（<code>*.jpg; *.jpeg; *.png; *.gif; *.bmp; *.webp; *.ico; *.svg; *.tif; *.tiff; *.psd; *.ai</code>）</li><li><code>:@video</code>：影片類（<code>*.mp4; *.mkv; *.avi; *.mov; *.wmv; *.flv; *.m4v; *.webm; *.3gp; *.rmvb; *.ts</code>）</li><li><code>:@audio</code>：音訊類（<code>*.mp3; *.wav; *.flac; *.aac; *.ogg; *.m4a; *.wma; *.ape</code>）</li><li><code>:@zip</code>：壓縮檔類（<code>*.zip; *.rar; *.7z; *.tar; *.gz; *.bz2; *.xz; *.iso</code>）</li></ul><p><strong>範例</strong>：</p><ul><li><code>財務 :@doc</code>：在文件中搜尋「財務」。</li><li><code>桌布 :@img</code>：在圖片中搜尋「桌布」。</li><li><code>clip :@video|audio</code>：在影片或音訊檔案中搜尋「clip」。</li></ul><p>你可以在<strong>設定 → 外掛模組 → CoreExtensions</strong>中自由修改分類規則或新增自訂分類。</p><h3 id="副檔名精準篩選-ext-或-ext1-ext2" tabindex="-1">副檔名精準篩選（<code>:.ext</code> 或 <code>:.ext1.ext2</code>） <a class="header-anchor" href="#副檔名精準篩選-ext-或-ext1-ext2" aria-label="Permalink to &quot;副檔名精準篩選（`:.ext` 或 `:.ext1.ext2`）&quot;">​</a></h3><p>使用點號直接指定一個或多個副檔名（會自動排除資料夾）：</p><ul><li><code>report :.pdf</code>：只保留 <code>.pdf</code> 檔案。</li><li><code>data :.csv.xlsx</code>：只保留 <code>.csv</code> 或 <code>.xlsx</code> 試算表檔案。</li></ul><h3 id="結果排序與檔案-資料夾篩選-scmaf" tabindex="-1">結果排序與檔案/資料夾篩選（<code>:[SCMAF]</code>） <a class="header-anchor" href="#結果排序與檔案-資料夾篩選-scmaf" aria-label="Permalink to &quot;結果排序與檔案/資料夾篩選（`:[SCMAF]`）&quot;">​</a></h3><p>使用單個字母指定排序屬性：<code>S</code>（檔案大小）、<code>C</code>（建立時間）、<code>M</code>（修改時間）、<code>A</code>（存取時間）、<code>F</code>（資料夾/檔案篩選）。</p><p>預設字母代表<strong>升冪</strong>（從小到大 / 從舊到新）；加入減號 <code>-</code>（前綴或後綴均可，如 <code>M-</code> 或 <code>:-M</code>）代表<strong>降冪</strong>（從大到小 / 從新到舊）或反向篩選：</p><table tabindex="0"><thead><tr><th style="text-align:left;">標記語法</th><th style="text-align:left;">效果說明</th><th style="text-align:left;">典型應用場景</th></tr></thead><tbody><tr><td style="text-align:left;"><code>:S</code></td><td style="text-align:left;">按檔案大小升冪排列（最小在前）</td><td style="text-align:left;">尋找空檔案或極小檔案</td></tr><tr><td style="text-align:left;"><code>:S-</code> 或 <code>:-S</code></td><td style="text-align:left;">按檔案大小降冪排列（最大在前）</td><td style="text-align:left;"><code>log :S-</code>（排查體積最大的記錄檔）</td></tr><tr><td style="text-align:left;"><code>:M</code></td><td style="text-align:left;">按修改時間升冪排列（最早修改在前）</td><td style="text-align:left;">尋找長期未更新的歷史檔案</td></tr><tr><td style="text-align:left;"><code>:M-</code> 或 <code>:-M</code></td><td style="text-align:left;">按修改時間降冪排列（最新修改在前）</td><td style="text-align:left;"><code>report :M-</code>（快速尋找最近修改過的文件）</td></tr><tr><td style="text-align:left;"><code>:C</code> / <code>:C-</code></td><td style="text-align:left;">按建立時間升冪 / 降冪排列</td><td style="text-align:left;"><code>build :C-</code>（尋找最新產生的建置產物）</td></tr><tr><td style="text-align:left;"><code>:A</code> / <code>:A-</code></td><td style="text-align:left;">按存取時間升冪 / 降冪排列</td><td style="text-align:left;"><code>project :A-</code>（尋找最近開啟過的專案）</td></tr><tr><td style="text-align:left;"><code>:F</code></td><td style="text-align:left;"><strong>僅保留資料夾</strong>（過濾掉所有普通檔案）</td><td style="text-align:left;"><code>config :F</code>（僅尋找名為 config 的目錄）</td></tr><tr><td style="text-align:left;"><code>:-F</code> 或 <code>:F-</code></td><td style="text-align:left;"><strong>僅保留檔案</strong>（過濾掉所有資料夾目錄）</td><td style="text-align:left;"><code>config :-F</code>（僅尋找名為 config 的檔案）</td></tr></tbody></table><h3 id="萬用字元二次篩選-表達式-或-表達式" tabindex="-1">萬用字元二次篩選（<code>:?&lt;表達式&gt;</code> 或 <code>?&lt;表達式&gt;</code>） <a class="header-anchor" href="#萬用字元二次篩選-表達式-或-表達式" aria-label="Permalink to &quot;萬用字元二次篩選（`:?&lt;表達式&gt;` 或 `?&lt;表達式&gt;`）&quot;">​</a></h3><p>使用標準 Windows 萬用字元（<code>?</code> 比對單個字元，<code>*</code> 比對任意字元序列）對結果進行精確比對，支援用 <code>|</code> 或 <code>;</code> 分隔多個 OR 條件：</p><ul><li><code>mp4 :?(2026???????????)</code>：比對包含 <code>2026</code> 且後跟 11 位時間戳記的影片檔案。</li><li><code>photo :?IMG_????.jpg|DSC_????.jpg</code>：同時比對兩種相機格式的特定相片編號。</li></ul><h3 id="路徑模糊二次比對-路徑表達式" tabindex="-1">路徑模糊二次比對（<code>::&lt;路徑表達式&gt;</code>） <a class="header-anchor" href="#路徑模糊二次比對-路徑表達式" aria-label="Permalink to &quot;路徑模糊二次比對（`::&lt;路徑表達式&gt;`）&quot;">​</a></h3><p>要求結果的任意一級上級目錄名或檔案名稱本身比對指定的模糊關鍵字：</p><ul><li><code>report ::2024</code>：要求檔案所在路徑的各級目錄中必須包含 <code>2024</code>。</li><li><code>main ::&quot;src\\core&quot;</code>：要求檔案位於 <code>src\\core</code> 及其子目錄下。</li></ul><h3 id="鏈式組合實戰範例" tabindex="-1">鏈式組合實戰範例 <a class="header-anchor" href="#鏈式組合實戰範例" aria-label="Permalink to &quot;鏈式組合實戰範例&quot;">​</a></h3><p>各個標記可以組合在同一個 <code>:</code> 後使用：</p><ul><li><code>財務報表 :@doc,M-</code>：搜尋「財務報表」，限定文件類型，按修改時間倒序排列（最新修改在前）。</li><li><code>backup :.zip,S-,:-F</code>：搜尋「backup」，限定 <code>.zip</code> 格式，按體積從大到小排列，且僅顯示檔案。</li><li><code>icon ::assets,?*128*</code>：搜尋「icon」，限定路徑包含 <code>assets</code>，且檔案名稱中包含 <code>128</code> 尺寸標識。</li></ul><h2 id="_6-特殊搜尋技巧" tabindex="-1">6. 特殊搜尋技巧 <a class="header-anchor" href="#_6-特殊搜尋技巧" aria-label="Permalink to &quot;6. 特殊搜尋技巧&quot;">​</a></h2><h3 id="單次搜尋臨時繞過排除規則" tabindex="-1">單次搜尋臨時繞過排除規則 <a class="header-anchor" href="#單次搜尋臨時繞過排除規則" aria-label="Permalink to &quot;單次搜尋臨時繞過排除規則&quot;">​</a></h3><p>在查詢最開頭輸入 <code>*</code>，可讓本次搜尋臨時忽略在<a href="./settings/index-drives.html#排除規則"><strong>排除規則</strong></a>中設定的路徑排除、Glob 和正則表達式，無需修改設定：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>*node_modules</span></span></code></pre></div><p><code>*</code> 本身會在搜尋前自動剝離，不會參與文字比對。該功能僅能召回已建立索引的內容（網路磁碟機或 WSL 中未被建立索引的排除項不會出現）；系統隱藏檔案等基礎過濾依然保持生效。</p><h3 id="結果類型觸發符" tabindex="-1">結果類型觸發符 <a class="header-anchor" href="#結果類型觸發符" aria-label="Permalink to &quot;結果類型觸發符&quot;">​</a></h3><p>在<strong>設定 → 一般 → 快速搜尋視窗 → 結果類型優先級</strong>中，可以為特定結果類型（應用程式、系統設定、檔案分類、外掛模組項目、普通檔案等）設定單字元<strong>觸發符</strong>。</p><p>在快速搜尋列最前面輸入該觸發符，將只顯示該類型的結果，其他類型全部隱藏：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>;vs</span></span></code></pre></div><p>若 <code>;</code> 被設定為「應用程式」類型的觸發符，上述輸入將只在應用程式中搜尋 Visual Studio。在快速搜尋與內嵌視窗中，歷史記錄與我的最愛不受觸發符影響，始終置頂展示。</p><h2 id="_7-多語言智能別名" tabindex="-1">7. 多語言智能別名 <a class="header-anchor" href="#_7-多語言智能別名" aria-label="Permalink to &quot;7. 多語言智能別名&quot;">​</a></h2><h3 id="中文檔名-拼音別名" tabindex="-1">中文檔名：拼音別名 <a class="header-anchor" href="#中文檔名-拼音別名" aria-label="Permalink to &quot;中文檔名：拼音別名&quot;">​</a></h3><p>內建拼音別名外掛模組（<code>PinyinAlias</code>），無需設定即可直接使用拼音搜尋中文檔案名稱：</p><ul><li><strong>全拼搜尋</strong>：輸入 <code>chongqing</code> 即可精準命中名為 <code>重慶.docx</code> 的檔案。</li><li><strong>簡拼 / 首字母</strong>：輸入 <code>cq</code> 同樣可比對 <code>重慶.docx</code>；輸入 <code>wzry</code> 可比對 <code>王者榮耀.exe</code>。</li><li><strong>多音字支援</strong>：系統會為漢字的常見讀音同時建立別名索引（如「重慶」可同時比對 <code>chongqing</code> 與 <code>zhongqing</code>，「銀行」可比對 <code>yinhang</code> 與 <code>yinxing</code>）。</li></ul><p>可在<strong>設定 → 外掛模組</strong>中確認 <code>PinyinAlias</code> 外掛模組是否處於啟用狀態。</p><h3 id="西班牙語檔名-重音別名" tabindex="-1">西班牙語檔名：重音別名 <a class="header-anchor" href="#西班牙語檔名-重音別名" aria-label="Permalink to &quot;西班牙語檔名：重音別名&quot;">​</a></h3><p>內建 <code>SpanishAlias</code> 外掛模組，支援使用標準無重音 ASCII 字母搜尋包含西班牙語重音字元（<code>á</code>、<code>é</code>、<code>í</code>、<code>ó</code>、<code>ú</code>、<code>ü</code>、<code>ñ</code>）的檔案名稱：</p><ul><li>輸入 <code>cancion</code> 比對 <code>Canción.mp3</code>。</li><li>輸入 <code>nino</code> 比對 <code>Niño.txt</code>。</li><li>輸入 <code>ciguena</code> 比對 <code>Cigüeña.png</code>。</li></ul><p>命中的字元（包含原檔案名稱中的重音字元）將保持精準反白。可在<strong>設定 → 外掛模組</strong>中管理 <code>SpanishAlias</code> 外掛模組。</p><h2 id="_8-常見疑問與我的最愛" tabindex="-1">8. 常見疑問與我的最愛 <a class="header-anchor" href="#_8-常見疑問與我的最愛" aria-label="Permalink to &quot;8. 常見疑問與我的最愛&quot;">​</a></h2><h3 id="我的最愛-而非自訂別名" tabindex="-1">我的最愛，而非自訂別名 <a class="header-anchor" href="#我的最愛-而非自訂別名" aria-label="Permalink to &quot;我的最愛，而非自訂別名&quot;">​</a></h3><p>Lertaro 並未設計通用的「自訂搜尋別名/巨集」機制。最接近的替代方案是<a href="./settings/favorites.html"><strong>我的最愛</strong></a>：將任意檔案、資料夾或網址加入我的最愛並指定自訂顯示名稱後，即可透過該名稱直接搜尋到它（結果中帶有 ★ 標記）。</p><p>如果你需要透過自訂關鍵字快速啟動外部程式或執行指令碼，請參閱<a href="./instant-answers.html#自訂命令"><strong>自訂命令</strong></a>。</p>',103)])])}const x=t(c,[["render",l]]);export{g as __pageData,x as default};
